  "PHP/APP/resources/views/admin/users/edit.blade.php": "@extends('layouts.app')\n@section('title', 'Edit User')\n@section('content')\n<div class=\"max-w-2xl mx-auto bg-white shadow rounded-lg p-8\">\n    <h1 class=\"text-2xl font-bold mb-6\">Edit User</h1>\n    <form method=\"POST\" action=\"{{ route('admin.users.update', $user) }}\" class=\"space-y-4\">\n        @csrf @method('PUT')\n        <div class=\"grid md:grid-cols-2 gap-4\">\n            <div>\n                <label class=\"block text-sm font-medium text-gray-700\">Name</label>\n                <input type=\"text\" name=\"name\" value=\"{{ old('name', $user->name) }}\" required class=\"mt-1 w-full rounded-md border-gray-300 shadow-sm\">\n            </div>\n            <div>\n                <label class=\"block text-sm font-medium text-gray-700\">Email</label>\n                <input type=\"email\" name=\"email\" value=\"{{ old('email', $user->email) }}\" required class=\"mt-1 w-full rounded-md border-gray-300 shadow-sm\">\n            </div>\n        </div>\n        <div class=\"grid md:grid-cols-2 gap-4\">\n            <div>\n                <label class=\"block text-sm font-medium text-gray-700\">Role</label>\n                <select name=\"role\" required class=\"mt-1 w-full rounded-md border-gray-300 shadow-sm\">\n                    @foreach(['intern','supervisor','admin'] as $r)\n                        <option value=\"{{ $r }}\" @selected(old('role',$user->role)==$r)>{{ ucfirst($r) }}</option>\n                    @endforeach\n                </select>\n            </div>\n            <div>\n                <label class=\"block text-sm font-medium text-gray-700\">Company</label>\n                <input type=\"text\" name=\"company\" value=\"{{ old('company', $user->company) }}\" class=\"mt-1 w-full rounded-md border-gray-300 shadow-sm\">\n            </div>\n        </div>\n        <div class=\"grid md:grid-cols-2 gap-4\">\n            <div>\n                <label class=\"block text-sm font-medium text-gray-700\">Department</label>\n                <input type=\"text\" name=\"department\" value=\"{{ old('department', $user->department) }}\" class=\"mt-1 w-full rounded-md border-gray-300 shadow-sm\">\n            </div>\n            <div>\n                <label class=\"block text-sm font-medium text-gray-700\">Phone</label>\n                <input type=\"text\" name=\"phone\" value=\"{{ old('phone', $user->phone) }}\" class=\"mt-1 w-full rounded-md border-gray-300 shadow-sm\">\n            </div>\n        </div>\n        <div class=\"grid md:grid-cols-2 gap-4\">\n            <div>\n                <label class=\"block text-sm font-medium text-gray-700\">New Password (optional)</label>\n                <input type=\"password\" name=\"password\" class=\"mt-1 w-full rounded-md border-gray-300 shadow-sm\">\n            </div>\n            <div>\n                <label class=\"block text-sm font-medium text-gray-700\">Confirm</label>\n                <input type=\"password\" name=\"password_confirmation\" class=\"mt-1 w-full rounded-md border-gray-300 shadow-sm\">\n            </div>\n        </div>\n        <div class=\"flex gap-3\">\n            <button class=\"bg-indigo-600 text-white px-4 py-2 rounded hover:bg-indigo-700\">Update</button>\n            <a href=\"{{ route('admin.users.index') }}\" class=\"px-4 py-2 text-gray-600 hover:underline\">Cancel</a>\n        </div>\n    </form>\n</div>\n@endsection",
