  "PHP/APP/resources/views/dashboard/intern.blade.php": "@extends('layouts.app')\n@section('title', 'Intern Dashboard')\n@section('content')\n<h1 class=\"text-2xl font-bold mb-6\">Intern Dashboard</h1>\n@if($internship)\n    <div class=\"bg-white shadow rounded-lg p-6 mb-6\">\n        <div class=\"flex justify-between items-center mb-2\">\n            <h2 class=\"font-semibold\">{{ $internship->company }} — {{ $internship->position }}</h2>\n            <span class=\"text-sm px-2 py-1 rounded bg-gray-100\">{{ $internship->status }}</span>\n        </div>\n        <div class=\"text-sm text-gray-500 mb-3\">Supervisor: {{ $internship->supervisor->name }} · Required: {{ $internship->required_hours }}h</div>\n        <div class=\"w-full bg-gray-200 rounded-full h-3\">\n            <div class=\"bg-indigo-600 h-3 rounded-full\" style=\"width: {{ $internship->progressPercent() }}%\"></div>\n        </div>\n        <div class=\"text-sm text-gray-600 mt-2\">{{ $internship->approvedHours() }} / {{ $internship->required_hours }} hours ({{ $internship->progressPercent() }}%)</div>\n    </div>\n@endif\n<div class=\"grid md:grid-cols-2 gap-6\">\n    <div class=\"bg-white shadow rounded-lg p-6\">\n        <div class=\"flex justify-between items-center mb-4\">\n            <h2 class=\"font-semibold\">Recent Logs</h2>\n            <a href=\"{{ route('logs.create') }}\" class=\"bg-indigo-600 text-white text-sm px-3 py-1 rounded hover:bg-indigo-700\">+ New Log</a>\n        </div>\n        <ul class=\"divide-y\">\n            @forelse($recentLogs as $log)\n                <li class=\"py-3 flex justify-between\">\n                    <div>\n                        <div class=\"font-medium\">{{ $log->log_date->format('M d, Y') }} · {{ $log->hours }}h</div>\n                        <div class=\"text-sm text-gray-500\">{{ $log->task }}</div>\n                    </div>\n                    <span class=\"text-xs px-2 py-1 rounded\n                        @if($log->status==='approved') bg-green-100 text-green-700\n                        @elseif($log->status==='rejected') bg-red-100 text-red-700\n                        @else bg-gray-100 text-gray-700 @endif\">{{ $log->status }}</span>\n                </li>\n            @empty\n                <li class=\"py-3 text-gray-500\">No logs yet.</li>\n            @endforelse\n        </ul>\n    </div>\n    <div class=\"bg-white shadow rounded-lg p-6\">\n        <h2 class=\"font-semibold mb-4\">Today's Log</h2>\n        @if($todayLog)\n            <p class=\"text-sm text-gray-600\">Already logged: {{ $todayLog->task }} ({{ $todayLog->hours }}h) — {{ $todayLog->status }}</p>\n            <a href=\"{{ route('logs.edit', $todayLog) }}\" class=\"text-indigo-600 text-sm hover:underline\">Edit</a>\n        @else\n            <p class=\"text-gray-500 text-sm mb-3\">You haven't logged today.</p>\n            <a href=\"{{ route('logs.create') }}\" class=\"bg-indigo-600 text-white text-sm px-3 py-1 rounded hover:bg-indigo-700\">Log today</a>\n        @endif\n    </div>\n</div>\n@endsection",
